import type { MyBoard, MyBoardPatch, MyBoards } from "@stallion/client-sync";
import { describe, expect, it } from "vitest";
import { mergeBoards, syncBoards } from "./my-boards";
import type { RecentBoard } from "./recents";

const local = (id: string, lastOpened: number, extra: Partial<RecentBoard> = {}): RecentBoard => ({
  id,
  name: id,
  lastOpened,
  thumbnail: "",
  renamedAt: 0,
  ...extra,
});

const remote = (boardId: string, lastOpened: number, extra: Partial<MyBoard> = {}): MyBoard => ({
  boardId,
  name: boardId,
  lastOpened,
  thumbnail: "",
  ...extra,
});

describe("mergeBoards", () => {
  it("keeps the newest lastOpened per board and sorts newest first", () => {
    const merged = mergeBoards(
      [local("a", 5), local("b", 1)],
      [remote("a", 2), remote("b", 9), remote("c", 3)],
    );
    expect(merged.map((b) => [b.id, b.lastOpened])).toEqual([
      ["b", 9],
      ["a", 5],
      ["c", 3],
    ]);
  });

  it("takes the server name unless this device renamed the board since the last sync", () => {
    const merged = mergeBoards(
      [local("a", 1, { name: "old" }), local("b", 1, { name: "mine", renamedAt: 7 })],
      [remote("a", 1, { name: "Sketchbook" }), remote("b", 1, { name: "theirs" })],
    );
    expect(merged.find((b) => b.id === "a")?.name).toBe("Sketchbook");
    expect(merged.find((b) => b.id === "b")).toMatchObject({ name: "mine", renamedAt: 7 });
  });

  it("takes the thumbnail from the newer side, falling back to whichever has one", () => {
    const merged = mergeBoards(
      [local("a", 5, { thumbnail: "local-a" }), local("b", 1, { thumbnail: "local-b" })],
      [remote("a", 2, { thumbnail: "server-a" }), remote("b", 3)],
    );
    expect(merged.find((b) => b.id === "a")?.thumbnail).toBe("local-a");
    expect(merged.find((b) => b.id === "b")?.thumbnail).toBe("local-b");
  });
});

describe("syncBoards", () => {
  const fakeApi = (server: MyBoard[], online = true) => {
    const puts: [string, MyBoardPatch][] = [];
    const api: MyBoards = {
      list: async () =>
        online
          ? { ok: true, value: server }
          : { ok: false, reason: "NetworkError", message: "offline" },
      upsert: async (boardId, patch) => {
        puts.push([boardId, patch]);
        return { ok: true, value: remote(boardId, 0) };
      },
      remove: async () => ({ ok: true, value: undefined }),
    };
    return { api, puts };
  };

  it("writes what the server lacks back to it and clears the pending rename", async () => {
    const { api, puts } = fakeApi([remote("a", 4, { name: "server" })]);
    const synced = await syncBoards(api, [local("a", 2, { name: "renamed", renamedAt: 9 })]);
    expect(synced).toMatchObject({ state: "Synced" });
    expect(synced.boards).toEqual([local("a", 4, { name: "renamed" })]);
    expect(puts).toEqual([["a", { name: "renamed" }]]);
  });

  it("keeps the device list when the server cannot be reached", async () => {
    const { api, puts } = fakeApi([], false);
    const boards = [local("a", 1)];
    const synced = await syncBoards(api, boards);
    expect(synced).toMatchObject({ state: "Failed", reason: "NetworkError", boards });
    expect(puts).toEqual([]);
  });
});

export function Landing() {
  const [, navigate] = useLocation();
  const [recents, setRecents] = useState<RecentBoard[]>(() => loadRecents(localStorage));
  const api = useMemo<MyBoards | undefined>(myBoardsForPage, []);
  const [remote, setRemote] = useState<Remote>(() =>
    api ? { state: "Syncing" } : { state: "LocalOnly" },
  );
  const recentsRef = useRef(recents);
  recentsRef.current = recents;

  useEffect(() => {
    if (!api) return;
    let live = true;
    syncBoards(api, loadRecents(localStorage)).then((synced) => {
      if (!live) return;
      saveRecents(localStorage, synced.boards);
      setRecents(synced.boards);
      setRemote(
        synced.state === "Synced"
          ? { state: "Synced" }
          : remoteAfter(synced.reason, synced.message),
      );
    });
    return () => {
      live = false;
    };
  }, [api]);

  const createBoard = () => navigate(`/b/${randomBoardId()}`);

  const editName = (id: string, name: string) => {
    setRecents((current) => renameRecent(current, id, name));
  };

  const commitName = (id: string) => {
    const current = recentsRef.current;
    saveRecents(localStorage, current);
    const board = current.find((recent) => recent.id === id);
    if (!api || !board || board.renamedAt === 0) return;
    const { renamedAt } = board;
    api.upsert(id, { name: board.name }).then((result) => {
      if (!result.ok) {
        setRemote(remoteAfter(result.reason, result.message));
        return;
      }
      setRecents((latest) => {
        const next = latest.map((recent) =>
          recent.id === id && recent.renamedAt === renamedAt ? { ...recent, renamedAt: 0 } : recent,
        );
        saveRecents(localStorage, next);
        return next;
      });
    });
  };

  const remove = (id: string) => {
    setRecents((current) => {
      const next = removeRecent(current, id);
      saveRecents(localStorage, next);
      return next;
    });
    api?.remove(id).then((result) => {
      if (!result.ok) setRemote(remoteAfter(result.reason, result.message));
    });
  };

  return (
    <main class="landing" data-sync={remote.state}>
      <header class="landing-header">
        <h1>Stallion</h1>
export const DEFAULT_BOARD = "default";

export type RecentBoard = {
  id: string;
  name: string;
  lastOpened: number;
  thumbnail: string;
  renamedAt: number;
};

export const RECENTS_KEY = "stallion:recents";

export const MAX_RECENTS = 200;

type RecentsStorage = Pick<Storage, "getItem" | "setItem">;

type StoredRecent = Omit<RecentBoard, "renamedAt"> & { renamedAt?: number };

const isStoredRecent = (value: unknown): value is StoredRecent => {
  if (typeof value !== "object" || value === null) return false;
  const { id, name, lastOpened, thumbnail, renamedAt } = value as Record<string, unknown>;
  return (
    typeof id === "string" &&
    typeof name === "string" &&
    typeof lastOpened === "number" &&
    typeof thumbnail === "string" &&
    (renamedAt === undefined || typeof renamedAt === "number")
  );
};

const fromStored = (stored: StoredRecent): RecentBoard => ({
  ...stored,
  renamedAt: stored.renamedAt ?? 0,
});

const seedDefault = (): RecentBoard[] => [
  { id: DEFAULT_BOARD, name: DEFAULT_BOARD, lastOpened: 0, thumbnail: "", renamedAt: 0 },
];

export const loadRecents = (storage: RecentsStorage): RecentBoard[] => {
  const raw = storage.getItem(RECENTS_KEY);
  if (raw === null) return seedDefault();
  try {
    const parsed: unknown = JSON.parse(raw);
    return Array.isArray(parsed) ? parsed.filter(isStoredRecent).map(fromStored) : [];
  } catch {
    return [];
  }
};

