import { homedir } from "node:os";
import { join } from "node:path";
import { chromium } from "playwright";
import { accessHeaders } from "../npm-scripts/env.mjs";

const BASE = "https://stallion.matthijs-f49.workers.dev";
const SHOTS = join(homedir(), "development", ".tmp", "stallion-forget");
const headers = accessHeaders();
if (!headers["CF-Access-Client-Id"]) throw new Error("no access env");
const id = `forget-${Date.now()}`;
const errors = [];

const browser = await chromium.launch({ headless: true });
const context = async (label) => {
  const ctx = await browser.newContext({ extraHTTPHeaders: headers, viewport: { width: 1280, height: 800 } });
  const page = await ctx.newPage();
  page.on("console", (m) => {
    if (m.type() === "error" && !/favicon/i.test(m.text() + (m.location()?.url ?? ""))) errors.push(`${label}: ${m.text()}`);
  });
  page.on("pageerror", (e) => errors.push(`${label}: ${e.message}`));
  return page;
};
const a = await context("A");
const b = await context("B");
const row = (page) => page.locator(`li.recent:has(input[aria-label="Name for board ${id}"])`);
const landing = async (page) => {
  await page.goto(`${BASE}/`);
  await page.waitForSelector('main.landing[data-sync="Synced"]', { timeout: 20000 });
};
const openBoard = async (page) => {
  const put = page.waitForResponse((r) => r.url().endsWith(`/api/me/boards/${id}`) && r.request().method() === "PUT");
  await page.goto(`${BASE}/b/${id}`);
  const res = await put;
  if (!res.ok()) throw new Error(`upsert answered ${res.status()}`);
};
const expectRow = async (page, present, step) => {
  const count = await row(page).count();
  if ((count > 0) !== present) throw new Error(`${step}: expected ${present ? "present" : "absent"}, count ${count}`);
  console.log(`ok ${step}`);
};

await openBoard(a);
await landing(a);
await expectRow(a, true, "A lists the new board");
await landing(b);
await expectRow(b, true, "B sees the board");
await b.screenshot({ path: join(SHOTS, "1-b-sees-board.png") });

const del = a.waitForResponse((r) => r.url().endsWith(`/api/me/boards/${id}`) && r.request().method() === "DELETE");
await row(a).locator(".recent-remove").click();
if ((await del).status() !== 204) throw new Error("delete not 204");
await expectRow(a, false, "A removed it");

await b.reload();
await b.waitForSelector('main.landing[data-sync="Synced"]', { timeout: 20000 });
await expectRow(b, false, "B reload: gone");
const stored = await b.evaluate(() => localStorage.getItem("stallion:recents") ?? "");
if (stored.includes(id)) throw new Error("B localStorage still holds the board");
console.log("ok B localStorage pruned");
await b.screenshot({ path: join(SHOTS, "2-b-after-removal.png") });

await openBoard(b);
await landing(b);
await expectRow(b, true, "B reopened: back");
await b.screenshot({ path: join(SHOTS, "3-b-revived.png") });
await landing(a);
await expectRow(a, true, "A sees the revived board");

await browser.close();
console.log(`console errors: ${errors.length}`);
for (const e of errors) console.log(e);
process.exit(errors.length ? 1 : 0);
EOF
cd ~/development/stallion-worktrees/forget && cap node .tmp/forget-check.mjs 2>&1 | tail -20

